                for(int i=0;i<4;i+=2){var h=fighters[i];var w=fighters[i+1];Require(h.Entity.Spouse==w.Entity.Name && w.Entity.Spouse==h.Entity.Name);foreach(var who in new[]{h,w}){who.Entity.Teleport(1002,444,292);Revora.Database.KnownPersons.LoadPartner(who);Revora.Database.KnownPersons.LoaderFriends(who);Revora.Database.KnownPersons.LoadMentor(who);HeartTalk(who,2319,0);}team(h,Team.Create,0);team(h,Team.InviteRequest,w.Entity.UID);team(w,Team.AcceptInvitation,h.Entity.UID);Require(h.Team!=null && h.Team==w.Team);HeartTalk(h,2319,1);var invites=(System.Collections.IDictionary)type.GetField("invites",instance).GetValue(current);Require(invites.Contains(w.Entity.UID));var invite=invites[w.Entity.UID];byte code=(byte)invite.GetType().GetField("Code",instance).GetValue(invite);HeartTalk(w,2319,0);HeartTalk(w,2319,code);Require(h.Map.BaseID==1090 && h.Entity.MapID==w.Entity.MapID);}
